function normalizarPalabra(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}

// Fix #16: familia completa de palabras de marketing de cursos, no solo
// "curso"/"cursos" -- "desde cero", "a experto", "para principiantes", etc.
// aparecen en decenas de nombres del catalogo y no indican tema real.
const EXCLUIR = new Set([
  'curso', 'cursos', 'cero', 'desde', 'experto', 'expertos', 'avanzado', 'avanzada',
  'principiante', 'principiantes', 'basico', 'basica', 'nivel', 'completo', 'completa',
