  // "Curso de primera infancia".
  'primera', 'primero', 'primeros', 'primeras', 'vez', 'veces',
]);

function palabrasSignificativas(s) {
  return normalizarPalabra(s).split(/\s+/).filter(w => w.length > 2 && !EXCLUIR.has(w));
}

// Fix #24: siglas ("SST" = Seguridad y Salud en el Trabajo).
function esSigla(consulta, nombre) {
  const q = normalizarPalabra(consulta).trim();
  if (!/^[a-z]{2,5}$/.test(q)) return false;
  const iniciales = normalizarPalabra(nombre).split(/\s+/)
    .filter(w => w.length > 2 && !['curso', 'cursos', 'del', 'los', 'las', 'para', 'con', 'sin', 'por'].includes(w))
    .map(w => w[0]).join('');
  return iniciales === q;
}

// Fix #32: "chat gpt" ~ "ChatGPT" (consulta sin espacios contenida en el nombre sin espacios, minimo 5 letras)
function contienePegado(a, b) {
  const qc = palabrasSignificativas(a).join('');
  if (qc.length < 5) return false;
  const n = palabrasSignificativas(b);
  // la consulta pegada debe coincidir con palabras CONSECUTIVAS completas del nombre ("chat gpt" ~ "chatgpt"),
  // no con un trozo cruzado entre palabras ("lenguas" NO es parte de "lengua de señas").
  for (let i = 0; i < n.length; i++) {
    let acc = '';
    for (let j = i; j < n.length; j++) { acc += n[j]; if (acc === qc) return true; if (acc.length >= qc.length) break; }
  }
  return false;
}

// Fix #32: que tanto de la consulta aparece en el nombre (1 = todas las palabras / sigla / pegado)
function puntajeCoincidencia(consulta, nombre) {
  if (esSigla(consulta, nombre) || contienePegado(consulta, nombre)) return 1;
  const q = palabrasSignificativas(consulta);
  if (!q.length) return 0;
  const n = new Set(palabrasSignificativas(nombre));
  return q.filter(w => n.has(w)).length / q.length;
}

// Fix #32: cuantas palabras del NOMBRE del curso aparecen en lo que escribio el usuario ("lengua de señas colombiana"
// gana sobre "lengua de señas argentina" si el usuario dijo "colombiana"). Sirve para ordenar.
function afinidadMensaje(nombre) {
  const m = new Set(palabrasSignificativas(userMessage));
  return palabrasSignificativas(nombre).filter(w => m.has(w)).length; // cantidad (no fraccion): no favorece nombres cortos
}

function compartenPalabraSignificativa(a, b) {
  if (!a || !b) return false;
  if (esSigla(a, b)) return true;
  const aWords = new Set(palabrasSignificativas(a));
  const bWords = palabrasSignificativas(b);
  return bWords.some(w => aWords.has(w)) || contienePegado(a, b);
}

// Fix #16: chequeo estricto para cuando hay que proteger un tema ya
// establecido -- exige que la palabra compartida tenga 5+ letras y este
// entre las primeras 2 palabras significativas del nombre del curso (donde
// suele estar el tema real, ej. "Curso de JAVA desde cero"), no en el
// relleno de marketing del final.
function matchFuerte(a, b) {
  if (!a || !b) return false;
  if (esSigla(a, b)) return true;
  const aWords = new Set(palabrasSignificativas(a));
  const bWords = palabrasSignificativas(b);
  // Fix #32: un tema corto y exacto ("uñas", "iso") cuenta si la consulta limpia tiene 2 palabras o menos
  return bWords.some((w, i) => i <= 1 && aWords.has(w) && (w.length >= 5 || aWords.size <= 2)) || (aWords.size <= 2 && contienePegado(a, b));
}

